// Invoices (/invoices): invoices linked to jobs by a real foreign key. GST (15%)
// and totals are generated by the database from the subtotal, and invoice
// numbers come from a sequence, so neither can be typed wrong. "Overdue" is not a
// stored status: it is a sent invoice past its due date. Gated by `invoicing`.
import { useState } from "react";
import { toast } from "sonner";
import { useInvoices, useJobs, usePermissions } from "@/lib/queries";
import { useCreateInvoice, useDeleteInvoice, useSetInvoiceStatus } from "@/lib/mutations";
import { nzToday } from "@/lib/dates";
import { friendlyError } from "@/lib/format";
import { INVOICE_CLS, SERVICE_LABEL, fmtDay, money } from "@/lib/jobsUi";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/Modal";
import type { Invoice, InvoiceStatus } from "@/lib/types";

type Tab = "all" | "draft" | "sent" | "overdue" | "paid";

function addDays(dateStr: string, n: number): string {
  const d = new Date(dateStr + "T12:00");
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}

export function Invoices() {
  const { data: invoices = [], isLoading } = useInvoices();
  const { canWrite } = usePermissions();
  const setStatus = useSetInvoiceStatus();
  const del = useDeleteInvoice();
  const canEdit = canWrite("invoicing");

  const [tab, setTab] = useState<Tab>("all");
  const [creating, setCreating] = useState(false);

  const today = nzToday();
  const cutoff = addDays(today, -30);
  const isOverdue = (i: Invoice) => i.status === "sent" && i.due_on < today;
  const sum = (list: Invoice[]) => list.reduce((a, i) => a + i.total, 0);

  const draft = invoices.filter((i) => i.status === "draft");
  const sent = invoices.filter((i) => i.status === "sent");
  const overdue = invoices.filter(isOverdue);
  const paidRecent = invoices.filter((i) => i.status === "paid" && (i.paid_on ?? "") >= cutoff);

  const shown =
    tab === "all"
      ? invoices
      : tab === "overdue"
        ? overdue
        : invoices.filter((i) => i.status === tab);

  const tabs: [Tab, string, number][] = [
    ["all", "All", invoices.length],
    ["draft", "Draft", draft.length],
    ["sent", "Sent", sent.length],
    ["overdue", "Overdue", overdue.length],
    ["paid", "Paid", invoices.filter((i) => i.status === "paid").length],
  ];

  function move(i: Invoice, status: InvoiceStatus) {
    setStatus.mutate(
      { id: i.id, status },
      {
        onSuccess: () => toast(`${i.number} marked ${status}`),
        onError: (e) => toast(friendlyError(e)),
      },
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Invoices</h1>
          <p className="text-sm text-muted-foreground">GST-inclusive totals, tied to the job they bill.</p>
        </div>
        {canEdit && (
          <Button size="sm" onClick={() => setCreating(true)}>
            + New invoice
          </Button>
        )}
      </div>

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        <Card label="Outstanding (sent)" value={money(sum(sent))} sub={`${sent.length} invoice${sent.length === 1 ? "" : "s"}`} />
        <Card label="Overdue" value={money(sum(overdue))} sub={`${overdue.length} invoice${overdue.length === 1 ? "" : "s"}`} warn={overdue.length > 0} />
        <Card label="Drafts to send" value={money(sum(draft))} sub={`${draft.length} invoice${draft.length === 1 ? "" : "s"}`} />
        <Card label="Paid, last 30 days" value={money(sum(paidRecent))} sub={`${paidRecent.length} invoice${paidRecent.length === 1 ? "" : "s"}`} />
      </div>

      <div className="flex gap-1 border-b">
        {tabs.map(([key, label, n]) => (
          <button
            key={key}
            onClick={() => setTab(key)}
            className={`-mb-px border-b-2 px-3 py-2 text-sm ${
              tab === key ? "border-primary font-medium" : "border-transparent text-muted-foreground"
            }`}
          >
            {label} <span className="text-xs text-muted-foreground">{n}</span>
          </button>
        ))}
      </div>

      {isLoading ? (
        <p className="py-12 text-center text-sm text-muted-foreground">Loading invoices…</p>
      ) : shown.length === 0 ? (
        <p className="py-12 text-center text-sm text-muted-foreground">No invoices here.</p>
      ) : (
        <div className="overflow-x-auto rounded-lg border">
          <table className="w-full text-left text-sm">
            <thead className="border-b bg-muted/40 text-xs uppercase text-muted-foreground">
              <tr>
                <th className="px-3 py-2">Invoice</th>
                <th className="px-3 py-2">Customer</th>
                <th className="px-3 py-2">Issued</th>
                <th className="px-3 py-2">Due</th>
                <th className="px-3 py-2 text-right">Subtotal</th>
                <th className="px-3 py-2 text-right">GST</th>
                <th className="px-3 py-2 text-right">Total</th>
                <th className="px-3 py-2">Status</th>
                {canEdit && <th className="px-3 py-2" />}
              </tr>
            </thead>
            <tbody>
              {shown.map((i) => {
                const st = isOverdue(i) ? "overdue" : i.status;
                return (
                  <tr key={i.id} className="border-b last:border-0">
                    <td className="whitespace-nowrap px-3 py-2 font-medium">{i.number}</td>
                    <td className="px-3 py-2">
                      <div>{i.jobs?.customer_name ?? "—"}</div>
                      <div className="text-xs text-muted-foreground">
                        {i.jobs ? `${SERVICE_LABEL[i.jobs.service_type]} · ${fmtDay(i.jobs.job_date)}` : ""}
                      </div>
                    </td>
                    <td className="whitespace-nowrap px-3 py-2">{fmtDay(i.issued_on)}</td>
                    <td className={`whitespace-nowrap px-3 py-2 ${st === "overdue" ? "font-medium text-destructive" : ""}`}>
                      {fmtDay(i.due_on)}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums">{money(i.subtotal)}</td>
                    <td className="px-3 py-2 text-right tabular-nums text-muted-foreground">{money(i.gst)}</td>
                    <td className="px-3 py-2 text-right font-medium tabular-nums">{money(i.total)}</td>
                    <td className="px-3 py-2">
                      <span className={`rounded px-2 py-1 text-xs font-medium ${INVOICE_CLS[st]}`}>
                        {st === "overdue" ? "Overdue" : i.status === "paid" ? "Paid" : i.status === "sent" ? "Sent" : "Draft"}
                      </span>
                    </td>
                    {canEdit && (
                      <td className="whitespace-nowrap px-3 py-2 text-right">
                        {i.status === "draft" && (
                          <Button variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={() => move(i, "sent")}>
                            Mark sent
                          </Button>
                        )}
                        {i.status === "sent" && (
                          <Button variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={() => move(i, "paid")}>
                            Mark paid
                          </Button>
                        )}
                        {i.status === "paid" && (
                          <Button variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={() => move(i, "sent")}>
                            Undo
                          </Button>
                        )}
                        {i.status === "draft" && (
                          <button
                            className="ml-1 text-muted-foreground hover:text-destructive"
                            title="Delete draft"
                            onClick={() =>
                              window.confirm(`Delete draft ${i.number}?`) &&
                              del.mutate(i.id, {
                                onSuccess: () => toast("Draft deleted"),
                                onError: (e) => toast(friendlyError(e)),
                              })
                            }
                          >
                            ✕
                          </button>
                        )}
                      </td>
                    )}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {creating && <NewInvoiceModal onClose={() => setCreating(false)} />}
    </div>
  );
}

function Card({ label, value, sub, warn }: { label: string; value: string; sub: string; warn?: boolean }) {
  return (
    <div className="rounded-lg border px-4 py-3">
      <div className={`text-xl font-bold tabular-nums ${warn ? "text-destructive" : ""}`}>{value}</div>
      <div className="text-xs text-muted-foreground">
        {label} · {sub}
      </div>
    </div>
  );
}

/** Pick a completed job that has no invoice yet; the subtotal defaults to its quote. */
function NewInvoiceModal({ onClose }: { onClose: () => void }) {
  const { data: jobs = [] } = useJobs();
  const { data: invoices = [] } = useInvoices();
  const create = useCreateInvoice();

  const invoiced = new Set(invoices.map((i) => i.job_id));
  const options = jobs.filter((j) => j.status === "completed" && !invoiced.has(j.id)).reverse();

  const [jobId, setJobId] = useState(options[0]?.id || "");
  const [subtotal, setSubtotal] = useState(options[0]?.quote_amount != null ? String(options[0].quote_amount) : "");
  const [dueOn, setDueOn] = useState(addDays(nzToday(), 14));

  function pick(id: string) {
    setJobId(id);
    const j = options.find((o) => o.id === id);
    setSubtotal(j?.quote_amount != null ? String(j.quote_amount) : "");
  }

  function onSave() {
    const amount = Number(subtotal);
    if (!jobId) return void toast("Choose a job");
    if (!subtotal || Number.isNaN(amount) || amount < 0) return void toast("Enter a valid amount");
    create.mutate(
      { jobId, subtotal: amount, dueOn },
      {
        onSuccess: () => {
          toast("Draft invoice created");
          onClose();
        },
        onError: (e) => toast(friendlyError(e)),
      },
    );
  }

  const gst = Number(subtotal) > 0 ? Math.round(Number(subtotal) * 15) / 100 : 0;

  return (
    <Modal onClose={onClose}>
      <h2 className="mb-4 text-lg font-semibold">New invoice</h2>
      {options.length === 0 ? (
        <p className="text-sm text-muted-foreground">Every completed job already has an invoice.</p>
      ) : (
        <div className="space-y-3">
          <label className="block text-sm">
            <span className="mb-1 block text-muted-foreground">Completed job</span>
            <select className="ipt" value={jobId} onChange={(e) => pick(e.target.value)}>
              {options.map((j) => (
                <option key={j.id} value={j.id}>
                  {j.customer_name} · {SERVICE_LABEL[j.service_type]} · {fmtDay(j.job_date)}
                </option>
              ))}
            </select>
          </label>
          <div className="grid grid-cols-2 gap-3">
            <label className="block text-sm">
              <span className="mb-1 block text-muted-foreground">Subtotal (ex GST)</span>
              <input className="ipt" type="number" min={0} step="0.01" value={subtotal} onChange={(e) => setSubtotal(e.target.value)} />
            </label>
            <label className="block text-sm">
              <span className="mb-1 block text-muted-foreground">Due date</span>
              <input className="ipt" type="date" value={dueOn} onChange={(e) => setDueOn(e.target.value)} />
            </label>
          </div>
          <p className="text-xs text-muted-foreground">
            GST at 15% will be {money(gst)}. The database calculates the final total and invoice number.
          </p>
        </div>
      )}
      <div className="mt-5 flex justify-end gap-2">
        <Button variant="outline" size="sm" onClick={onClose}>
          Cancel
        </Button>
        {options.length > 0 && (
          <Button size="sm" onClick={onSave} disabled={create.isPending}>
            Create draft
          </Button>
        )}
      </div>
    </Modal>
  );
}
